def parse_bool(s):
    t = s.strip().lower()
    if t in ('true', '1', 'yes', 'on'):
        return True
    if t in ('false', '0', 'no', 'off', ''):
        return False
    raise ValueError(f'no es un booleano valido: {s!r}')

